            parts = listOf(
                StoryPart(1, "The Empty Windows", listOf("When Nia joined the school environment club, she noticed empty window boxes in the old science block.", "A faded label called them the Living Windows Project, but no plants remained. Their teacher said neighbours once helped students care for them.", "Nia suggested finding the original plan before planting anything new.")),
                StoryPart(2, "A List of Names", listOf("The club found a folder listing volunteers and sketches of each window.", "Some names belonged to retired teachers; others matched people still living nearby. Notes said every window had been assigned a local plant.", "Nia asked the school office to help contact former volunteers.")),
                StoryPart(3, "The First Visitor", listOf("Mrs Bello, a retired teacher, recognised the folder and explained that the windows were an outdoor classroom.", "Students once compared leaves, observed pollinators, and kept weekly notes. Neighbours donated seedlings, but the project belonged to the whole school.", "She remembered one window that had never grown well.")),
                StoryPart(4, "The Missing Label", listOf("Old photographs revealed that the missing label read 'Window Seven: plants that welcome butterflies'.", "A local gardener explained that the box received afternoon sun. The students researched plants suited to those conditions.", "They agreed to ask the groundskeeper before making changes.")),
                StoryPart(5, "A Different Record", listOf("The folder's observation chart stopped halfway through a term. Nia wondered why the project had ended.", "Mrs Bello remembered that the volunteer coordinator had moved away. Without a rota, watering became irregular and the students gradually stopped visiting.", "The club realised that a new garden needed shared responsibilities and a holiday plan.")),
                StoryPart(6, "The Neighbourhood Meeting", listOf("Nia invited former volunteers to a meeting in the library. They brought photographs, plant notes, and memories.", "A neighbour offered to identify suitable plants; another volunteered to check drainage with the maintenance team.", "The group assigned student pairs and adult contacts to each window.")),
                StoryPart(7, "Planting Day", listOf("After approval, the club prepared the boxes with the groundskeeper and used suitable soil.", "Each pair added a weatherproof label with the plant name and an observation question. Window Seven received plants chosen for its light.", "Nia displayed the old photographs beside the science room.")),
                StoryPart(8, "A Difficult Week", listOf("A hot week arrived, and some leaves began to droop. The students discovered two missed watering shifts.", "Instead of blaming anyone, they adjusted the rota, asked for advice, and added a holiday contact list.", "The plants recovered, and the club recorded the mistake and what it taught them.")),
                StoryPart(9, "The Open Windows", listOf("At open day, visitors read the labels. Former volunteers recognised their project, while younger students asked to join.", "Nia displayed the original folder beside the new observation binder. The records showed how the garden improved through attention.", "Mrs Bello said the best part was seeing students learn together.")),
                StoryPart(10, "A Living Archive", listOf("By term's end, the club had recorded growth, visiting insects, weather changes, and the adjustments that helped each box thrive.", "The school recruited volunteers for the next term and shared a copy of the archive with the library.", "Nia understood that the plants mattered, but so did noticing, recording, sharing, and returning. The Living Windows Project had begun again with a stronger plan and a larger community."))
